220	func (node *Node) serve() {
221		defer node.running.Done()
222		for {
223			select {
224			case <-node.shutdownChan:
225				return
226			case m := <-node.in:
227				node.RLock()
228				handler := node.h
229				node.RUnlock()
230				switch msg := m.message.(type) {
231				case *smartbftprotos.Message:
232					if node.app != nil && node.app.messageLost != nil && node.app.messageLost(msg) {
233						continue
234					}
235					handler.HandleMessage(uint64(m.from), msg)
236				default:
237					handler.HandleRequest(uint64(m.from), msg.(*FwdMessage).Payload)
238				}
239			}
240		}
241	}
